import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])

    if n == 1:
        print(1)
        print(1)
        return

    primes = [False] * (n + 2)
    for i in range(2, n + 2):
        primes[i] = True

    for i in range(2, int((n + 2) ** 0.5) + 1):
        if primes[i]:
            for j in range(i * i, n + 2, i):
                primes[j] = False

    colors = []
    for i in range(1, n + 1):
        price = i + 1
        if primes[price]:
            colors.append(2)
        else:
            colors.append(1)

    print(2)
    print(" ".join(map(str, colors)))

if __name__ == "__main__":
    main()
